package store

// migration6SQL is migration 6 (call notices in Courier's words) frozen as text: every call notice already on disk
// read as a new one is (annotateCallNoteSQL with its chat's network; only a row whose reading differs is written),
// and the two kinds that had no action message of their own (Signal's "Call ended", Telegram's call record),
// indexed as text until now, out of the search index.
// It is text, not built from annotateCallNoteSQL, so a bridge that rewords its notices later changes what the engine
// reads from then on, never a migration already run on someone's disk. TestMigration6IsTheLiveHelperToday checks the
// two agree as this ships. Never edit it: a change is a new migration.
const migration6SQL = `UPDATE events SET content = (CASE WHEN NOT json_valid(content) OR (CASE WHEN json_valid(content) THEN json_type(content, '$."fi.courier.call"') END) IS NOT NULL THEN content
  WHEN (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) = 'object' THEN (CASE WHEN (CASE WHEN json_valid(content) THEN json_extract(content, '$."com.beeper.action_message".type') END) = 'call' THEN json_set(content, '$."fi.courier.call"', json(json_object('state', (CASE WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Started a video chat' THEN 'started'
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Ended the video chat (*)' THEN 'ended'
  ELSE 'ringing' END), 'media', (CASE WHEN (CASE WHEN json_valid(content) THEN json_extract(content, '$."com.beeper.action_message".call_type') END) IN ('voice', 'video') THEN (CASE WHEN json_valid(content) THEN json_extract(content, '$."com.beeper.action_message".call_type') END) ELSE '' END)))) ELSE content END)
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'signal' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Call ended'
    THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'ended', 'media', '')))
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND ((CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Call missed' OR (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Call missed (*)') THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'missed', 'media', 'voice')))
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND ((CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Call disconnected' OR (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Call disconnected (*)') THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'dropped', 'media', 'voice')))
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND ((CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Call ended' OR (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Call ended (*)') THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'ended', 'media', 'voice')))
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND ((CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Call rejected' OR (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Call rejected (*)') THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'declined', 'media', 'voice')))
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND ((CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Video call missed' OR (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Video call missed (*)') THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'missed', 'media', 'video')))
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND ((CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Video call disconnected' OR (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Video call disconnected (*)') THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'dropped', 'media', 'video')))
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND ((CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Video call ended' OR (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Video call ended (*)') THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'ended', 'media', 'video')))
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND ((CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Video call rejected' OR (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Video call rejected (*)') THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'declined', 'media', 'video')))
  ELSE content END)
  WHERE type = 'm.room.message' AND content LIKE '%call%' AND content IS NOT (CASE WHEN NOT json_valid(content) OR (CASE WHEN json_valid(content) THEN json_type(content, '$."fi.courier.call"') END) IS NOT NULL THEN content
  WHEN (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) = 'object' THEN (CASE WHEN (CASE WHEN json_valid(content) THEN json_extract(content, '$."com.beeper.action_message".type') END) = 'call' THEN json_set(content, '$."fi.courier.call"', json(json_object('state', (CASE WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Started a video chat' THEN 'started'
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Ended the video chat (*)' THEN 'ended'
  ELSE 'ringing' END), 'media', (CASE WHEN (CASE WHEN json_valid(content) THEN json_extract(content, '$."com.beeper.action_message".call_type') END) IN ('voice', 'video') THEN (CASE WHEN json_valid(content) THEN json_extract(content, '$."com.beeper.action_message".call_type') END) ELSE '' END)))) ELSE content END)
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'signal' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Call ended'
    THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'ended', 'media', '')))
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND ((CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Call missed' OR (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Call missed (*)') THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'missed', 'media', 'voice')))
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND ((CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Call disconnected' OR (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Call disconnected (*)') THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'dropped', 'media', 'voice')))
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND ((CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Call ended' OR (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Call ended (*)') THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'ended', 'media', 'voice')))
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND ((CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Call rejected' OR (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Call rejected (*)') THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'declined', 'media', 'voice')))
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND ((CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Video call missed' OR (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Video call missed (*)') THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'missed', 'media', 'video')))
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND ((CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Video call disconnected' OR (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Video call disconnected (*)') THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'dropped', 'media', 'video')))
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND ((CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Video call ended' OR (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Video call ended (*)') THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'ended', 'media', 'video')))
  WHEN (SELECT network FROM rooms WHERE rooms.room_id = events.room_id) = 'telegram' AND (CASE WHEN json_valid(content) THEN json_extract(content, '$.msgtype') END) = 'm.notice' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) IS NULL AND ((CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) = 'Video call rejected' OR (CASE WHEN json_valid(content) THEN json_extract(content, '$.body') END) GLOB 'Video call rejected (*)') THEN json_set(content, '$."com.beeper.action_message"', json('{"type":"call"}'), '$."fi.courier.call"', json(json_object('state', 'declined', 'media', 'video')))
  ELSE content END);
DELETE FROM search_messages WHERE rowid IN (SELECT doc_id FROM events WHERE doc_id IS NOT NULL AND content LIKE '%fi.courier.call%' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) = 'object');
UPDATE events SET doc_id = NULL WHERE doc_id IS NOT NULL AND content LIKE '%fi.courier.call%' AND (CASE WHEN json_valid(content) THEN json_type(content, '$."com.beeper.action_message"') END) = 'object';`
